     *
     * @param     string $relationAlias optional alias for the relation
     * @param     string $joinType Accepted values are null, 'left join', 'right join', 'inner join'
     *
     * @return EnviadaDirectorioQuery The current query, for fluid interface
     */
    public function joinRolDirenviada($relationAlias = null, $joinType = Criteria::INNER_JOIN)
    {
        $tableMap = $this->getTableMap();
        $relationMap = $tableMap->getRelation('RolDirenviada');

        // create a ModelJoin object for this join
        $join = new ModelJoin();
        $join->setJoinType($joinType);
        $join->setRelationMap($relationMap, $this->useAliasInSQL ? $this->getModelAlias() : null, $relationAlias);
        if ($previousJoin = $this->getPreviousJoin()) {
            $join->setPreviousJoin($previousJoin);
        }

        // add the ModelJoin to the current object
        if ($relationAlias) {
            $this->addAlias($relationAlias, $relationMap->getRightTable()->getName());
            $this->addJoinObject($join, $relationAlias);
        } else {
            $this->addJoinObject($join, 'RolDirenviada');
        }

        return $this;
    }

    /**
     * Use the RolDirenviada relation RolDirenviada object
     *
     * @see       useQuery()
     *
     * @param     string $relationAlias optional alias for the relation,
     *                                   to be used as main alias in the secondary query
     * @param     string $joinType Accepted values are null, 'left join', 'right join', 'inner join'
     *
     * @return   RolDirenviadaQuery A secondary query class using the current class as primary query
     */
    public function useRolDirenviadaQuery($relationAlias = null, $joinType = Criteria::INNER_JOIN)
    {
        return $this
            ->joinRolDirenviada($relationAlias, $joinType)
            ->useQuery($relationAlias ? $relationAlias : 'RolDirenviada', 'RolDirenviadaQuery');
    }

    /**
     * Exclude object from result
     *
     * @param   EnviadaDirectorio $enviadaDirectorio Object to remove from the list of results
     *
     * @return EnviadaDirectorioQuery The current query, for fluid interface
     */
    public function prune($enviadaDirectorio = null)
    {
        if ($enviadaDirectorio) {
            $this->addUsingAlias(EnviadaDirectorioPeer::ENVIADADIRECTORIO_ID, $enviadaDirectorio->getEnviadadirectorioId(), Criteria::NOT_EQUAL);
        }

        return $this;
    }

